def reduce_if_selected(path,raw):
 raw=authorization_delta.reduce_if_selected(path,raw)
 if path not in SOURCE_INPUTS:return raw
 if hashlib.sha256(raw).hexdigest()==BASE_PINS[path]:return raw
 if hashlib.sha256(raw).hexdigest()!=SOURCE_INPUTS[path]:raise ValueError('unreviewed partial schema or media binding')
 added,removed=EDITS[path][0]
 if raw!=added:raise ValueError('partial exact inverse changed')
 if hashlib.sha256(removed).hexdigest()!=BASE_PINS[path]:raise ValueError('partial baseline changed')
 return removed
def assert_cohort(root,reader):
 from pathlib import Path
 choices=[]
 for path in SOURCE_INPUTS:
  pin=hashlib.sha256(authorization_delta.reduce_if_selected(path,reader(Path(root)/path))).hexdigest()
  if pin not in (SOURCE_INPUTS[path],BASE_PINS[path]):raise ValueError('partial source cohort changed')
  choices.append(pin==SOURCE_INPUTS[path])
 if any(choices)and not all(choices):raise ValueError('partial source cohort mixed')
